use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let key = "seen";

        // Merge the newly considered ids into the persisted seen-set.
        let mut seen: Vec<String> = match state_rw::get(key) {
            Some(existing) if !existing.is_empty() => {
                existing.split('\u{1e}').map(|s| s.to_string()).collect()
            }
            _ => Vec::new(),
        };

        let mut recorded: u32 = 0;
        for id in &published.considered {
            if !seen.iter().any(|s| s == id) {
                seen.push(id.clone());
                recorded += 1;
            }
        }

        let joined = seen.join("\u{1e}");
        state_rw::put(key, &joined);

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
